CREATE OR REPLACE FUNCTION public.prevent_permission_identifier_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.identifier IS DISTINCT FROM OLD.identifier THEN
        RAISE EXCEPTION 'Permission identifiers cannot be changed.';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_record_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW."updated_at" = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$function$
